def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "deliver_to_table1": And([
            Not(self.host_signal_received),
            self.host_is_present,
            self.bar_is_crowded,
            Not(self.robot_has_social_awareness)
        ]),
        "deliver_to_table2": And([
            Not(self.host_signal_received),
            self.host_is_present,
            self.bar_is_crowded,
            Not(self.robot_has_social_awareness)
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
